using System;using System.IO;using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using UnityEngine.Tilemaps;using Rootborn.Game.Common;using Rootborn.Game.Placement;namespace Rootborn.Tests.EditMode.Interiors{public sealed class StudentActivityArtAssetTests{
[TestCase("paint_can")][TestCase("wallpaper_samples")][TestCase("training_tire")]public void ActivityPropIsRegisteredWithOneCellFootprintAndFloorPivot(string name){string path="Assets/Art/CareerFurniture/Activity31/Activity31_"+name+"_1x1.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(48,96)));Assert.That(s.pivot,Is.EqualTo(new Vector2(24,24)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));var f=AssetDatabase.LoadAssetAtPath<FurnitureDefinition>("Assets/Data/Interiors/Furniture/Activity31/Furniture_Activity31_"+name+".asset");Assert.That(f,Is.Not.Null);Assert.That(f.FootprintCells,Is.EquivalentTo(new[]{Vector2Int.zero}));Assert.That(f.AllowedSurfaceIds,Does.Contain("house"));Assert.That(AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset").FurnitureDefinitions,Does.Contain(f));var tile=f.TileParts[0].Tile as Tile;Assert.That(tile.sprite,Is.SameAs(s));var settings=AddressableAssetSettingsDefaultObject.Settings;foreach(var o in new UnityEngine.Object[]{s,tile,f})Assert.That(settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(o))),Is.Not.Null);}
[Test]public void SnackReplacementPreservesRegisteredSpriteGuidAndFloorGeometry(){string path="Assets/Art/StudentLifePixels/Furniture48/StudentLife_snack_delivery_crate_1x1.png";Assert.That(AssetDatabase.AssetPathToGUID(path),Is.EqualTo(File.ReadAllText("output/design-comfy-20261031/evidence/original-snack-guid.txt").Trim()));var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s.rect.size,Is.EqualTo(new Vector2(48,96)));Assert.That(s.pivot,Is.EqualTo(new Vector2(24,24)));var f=AssetDatabase.LoadAssetAtPath<FurnitureDefinition>("Assets/Data/Interiors/Furniture/StudentLifePixels/Furniture48/Furniture_StudentLife_snack_delivery_crate.asset");Assert.That(f.StableId,Is.EqualTo("studentlife.snack.delivery.crate"));Assert.That((f.TileParts[0].Tile as Tile).sprite,Is.SameAs(s));}
}}
